import json,hashlib,copy,shutil
from pathlib import Path
R=Path.cwd();O=R/'outputs/expanded/key_moments/subtypes';N=R/'outputs/expanded/key_moments/native_review'
def read(p):return json.loads(p.read_text())
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def save(name,x): (O/name).write_text(json.dumps(x,indent=2))
original={str(p.relative_to(O)):sha(p) for p in [O/'scores.json',O/'case_scores.json',O/'frozen_references.json',*sorted((O/'references').glob('*.json'))]}
rows=read(O/'case_scores.json');overlay=[]
for c,t in [('H',4),('H',8),('H',12),('H',16),('G',8)]:
 p=N/f'{c}_{t}.json';a=read(p)['targets']['strike_attempt'];sources=[{'path':str(p.relative_to(O.parent.parent.parent)), 'sha256':sha(p)}]
 timing=None
 if c=='H' and t==8:
  q=N/'H_8_onset_supplement.json';timing=read(q)['strike_attempt'];sources.append({'path':str(q.relative_to(O.parent.parent.parent)),'sha256':sha(q)})
 originaltruth=next(r['truth'] for r in rows if r['clip']==c and r['cutoff']==t and r['target']=='ground_strike_attempt')
 overlay.append({'clip':c,'cutoff':t,'target':'ground_strike_attempt','original_truth':originaltruth,'sensitivity_truth':a['occurrence'],'native_reference':a,'timing_supplement':timing,'sources':sources,'mapping_reason':'Past prefix is ground; independently reviewed macro strike attempt therefore maps to ground_strike_attempt only. No other subtype is overwritten.'})
 for r in rows:
  if r['clip']==c and r['cutoff']==t and r['target']=='ground_strike_attempt':
   assert r['past_phase']=='ground';r['truth']=a['occurrence'];r['eligible']=a['occurrence']!='unclear';y=1 if r['truth']=='yes' else 0;r['brier']=(r['probability']-y)**2 if r['eligible'] else None;r['reference_basis']='independent_native_sensitivity'
summaries=[]
for old in read(O/'scores.json'):
 s=copy.deepcopy(old);allrs=[r for r in rows if r['subset']==s['subset'] and (s['past_phase']=='all' or r['past_phase']==s['past_phase']) and r['condition']==s['condition'] and r['target']==s['target']];rs=[r for r in allrs if r['eligible']];pos=sum(r['truth']=='yes' for r in rs);neg=sum(r['truth']=='no' for r in rs);tp=sum(r['alert'] and r['truth']=='yes' for r in rs);fp=sum(r['alert'] and r['truth']=='no' for r in rs)
 s.update(eligible=len(rs),positives=pos,negatives=neg,unclear=len(allrs)-len(rs),mean_brier=sum(r['brier'] for r in rs)/len(rs) if rs else None,true_alerts=tp,false_alerts=fp,missed_positives=pos-tp,true_negatives=neg-fp,accuracy_at_0_5=(tp+neg-fp)/len(rs) if rs else None,precision=tp/(tp+fp) if tp+fp else None,recall=tp/pos if pos else None,false_alarm_rate=fp/neg if neg else None);summaries.append(s)
save('native_sensitivity.json',{'scope':'Selected H/G ground-strike targets only; model-reviewed references, not human gold. Frozen originals and forecasts unchanged. Native disagreement is a sensitivity analysis, not consensus. E16 generic strike ambiguity does not overwrite subtype-specific references.','overlays':overlay});save('sensitivity_case_scores.json',rows);save('sensitivity_scores.json',summaries)
(O/'native_sensitivity_report.txt').write_text('Independent native-frame sensitivity, selected ground cases only\n\nFrozen ordinary ground: 6 positive, 0 negative, 2 unclear; 4/6 positive alerts; Brier 0.207633.\nNative sensitivity: 3 positive, 0 negative, 5 unclear; 1/3 positive alerts; Brier 0.279633.\nH4/H12/H16 become unclear; H8/G8 remain yes. H8 timing supplement places one new onset at 11.7784–11.8452, before horizon end12.\nPredictors have not changed. These different scores reflect reference/denominator changes, not measured degradation or improvement. Neither reference set contains a ground negative, so false-alarm control remains untested. No model consensus or human-gold claim.\nE16 subtype references remain frozen; a generic ambiguous strike does not determine punch/kick subtype. Selected overlapping B and K windows remain separate stress episodes.\n')
assert all(sha(O/name)==h for name,h in original.items())
K=O/'extension_K';data={'scores':read(O/'scores.json'),'sensitivityScores':summaries,'rows':read(O/'case_scores.json'),'sensitivityRows':rows,'kScores':read(K/'scores.json'),'kRows':read(K/'case_scores.json'),'overlays':overlay,'cases':[]}
for folder,cs in [(O,[(c,t) for c in 'EFGH' for t in [4,8,12,16]]+[('B',t) for t in [4,6,7]]),(K,[('K',t) for t in [4,6,7]])]:
 for c,t in cs:
  ref=read(folder/'references'/f'{c}_{t}.json');pred=read(folder/'predictions'/f'{c}_{t}.json');prefix=read(folder/'prefixes'/f'{c}_{t}.json');data['cases'].append({'clip':c,'cutoff':t,'phase':prefix[-1]['end_phase'],'ref':ref,'pred':pred,'base':'extension_K/' if c=='K' else ''})
HTML='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MMA · Four seconds ahead</title><style>
:root{--bg:#10171c;--panel:#18242c;--ink:#edf0e9;--muted:#a5b4bc;--cyan:#22d3ee;--coral:#fb7185;--gold:#f4cc6a}*{box-sizing:border-box}body{background:var(--bg);color:var(--ink);margin:0;font:16px/1.5 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}main{max-width:1180px;margin:auto;padding:34px 22px}h1,h2{font-family:Impact,"Arial Narrow",sans-serif;font-weight:400;letter-spacing:.015em}h1{font-size:clamp(40px,6vw,70px);line-height:1;margin:14px 0}h2{font-size:28px}.eyebrow,.mono{font:12px ui-monospace,monospace;letter-spacing:.07em}.eyebrow{color:var(--cyan)}p{max-width:850px}a{color:var(--cyan);text-underline-offset:4px}button,select{font:inherit;color:var(--ink);background:var(--panel);border:1px solid #50616b;border-radius:3px;padding:9px 13px}button{cursor:pointer}button.active{background:var(--cyan);color:var(--bg);border-color:var(--cyan)}:focus-visible{outline:3px solid var(--gold);outline-offset:3px}.controls{display:flex;gap:12px;flex-wrap:wrap;margin:22px 0}.controls label{display:grid;gap:5px;font-size:12px;color:var(--muted)}.phases{display:flex;gap:6px;align-items:end}.note{border-left:3px solid var(--gold);padding:12px 18px;background:var(--panel)}.muted{color:var(--muted)}.scroll{overflow-x:auto}table{width:100%;border-collapse:collapse;font-size:14px}th{text-align:left;color:var(--muted);font-weight:400;font-size:12px}td,th{padding:13px 9px;border-bottom:1px solid #34434c;vertical-align:top}td.num{font-family:ui-monospace,monospace}td a{white-space:nowrap}.yes{color:var(--cyan)}.no{color:var(--coral)}.unclear{color:var(--gold)}.bar{height:6px;background:#34434c;min-width:110px;margin-top:7px;position:relative}.bar:after{content:"";position:absolute;left:50%;top:-3px;height:12px;border-left:1px solid var(--ink)}.bar span{display:block;height:6px;background:var(--cyan)}.split{display:grid;grid-template-columns:1fr 1fr;gap:22px}.panel{background:var(--panel);padding:20px;margin-top:20px}details{margin-top:12px}summary{cursor:pointer;color:var(--cyan)}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:12px/1.5 ui-monospace,monospace;max-height:440px;overflow:auto}footer{margin-top:38px;padding-top:20px;border-top:1px solid #34434c;font-size:13px;color:var(--muted)}@media(max-width:760px){.split{grid-template-columns:1fr}main{padding:24px 14px}td,th{padding:10px 7px}}
</style><main><div class="eyebrow">MMA EXPERIMENT / SOL 6.1 / NO TRAINING</div><h1>Four seconds ahead.</h1><p>Can rich past annotations anticipate the next committed punch, kick, ground strike or grappling attack? Inspect the probability beside the independently reviewed future. These are attempt forecasts; clean contact and damage are separate questions.</p><p class="muted">22 forecasts · 22 independent subtype references · three ordinary source bouts, plus two selected stress episodes. Each forecast receives only structured annotations ending at its cutoff.</p><div class="controls"><label>Case family<select id="subset"><option value="ordinary_registered">Ordinary E–H</option><option value="selected_takedown_stress_test">B · selected takedown episode</option><option value="K">K · selected ground episode</option></select></label><label>Reference view<select id="basis"><option value="frozen">Frozen subtype review</option><option value="native">Independent native sensitivity</option></select></label><div class="phases" aria-label="Past phase"><button data-phase="standing" class="active">Standing</button><button data-phase="clinch">Clinch</button><button data-phase="ground">Ground</button><button data-phase="all">All phases</button></div></div><p class="note" id="note"></p><h2>Relevant targets</h2><div class="scroll"><table><thead><tr><th>Target</th><th>Yes / no / unknown</th><th>Positive alerts / misses</th><th>False alerts / negatives</th><th>Brier ↓</th><th>Always yes / no / ½</th></tr></thead><tbody id="scores"></tbody></table></div><div class="controls"><label>Inspect target<select id="target"></select></label></div><h2>Forecasts, with their evidence</h2><p class="muted">Alert threshold 50%. Unknown references are displayed and excluded from numerical scores. Phase is measured from the past prefix, not chosen after seeing the future.</p><div class="scroll"><table><thead><tr><th>Cutoff → horizon</th><th>Past phase</th><th>Forecast</th><th>Future reference</th><th>Evidence / exact inputs</th></tr></thead><tbody id="cases"></tbody></table></div><div class="split"><section class="panel"><h2>What this says</h2><p>Standing punches and kicks have only one observed positive and one negative each. Both positive alerts also have a false alert. Clinch punches and knee/elbow attempts are missed in the eligible cases. Ground-strike alerts are sensitive to unresolved visual references.</p><p>The selected B episode contains three overlapping takedown positives; all are missed. Submissions have no observed positive, so their predictability has not been tested.</p></section><section class="panel"><h2>What it cannot say</h2><p>These windows are correlated and selected, not independent matches or a calibrated deployment sample. Negative-only targets and out-of-phase negatives can make aggregate accuracy look impressive. No ground negative is available to assess ground false alarms.</p><p>Model-reviewed labels remain fallible. The native sensitivity changes only selected H/G ground-strike references; it does not average models into a gold label.</p></section></div><footer><a href="report.txt">Study report</a> · <a href="protocol.json">Definitions & protocol</a> · <a href="verification.json">Input / causality checks</a> · <a href="native_sensitivity.json">Native sensitivity lineage</a> · <a href="reproduce/README.txt">Reproduce / source</a> · <a href="../../assessment/index.html">Overall assessment</a></footer></main><script id="data" type="application/json">__DATA__</script><script>
const D=JSON.parse(document.querySelector('#data').textContent);let phase='standing';const $=s=>document.querySelector(s);const names={punch_attempt:'Punch · standing / clinch',kick_attempt:'Kick · standing / clinch',knee_elbow_attempt:'Knee / elbow · standing / clinch',ground_strike_attempt:'Ground strike · any limb',takedown_attempt:'Takedown attempt',submission_entry:'Submission entry'};const keys=Object.keys(names);const esc=s=>String(s??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));const fmt=n=>n==null?'—':n.toFixed(3);const targets=()=>phase==='ground'?keys.slice(3):phase==='standing'||phase==='clinch'?keys.filter(k=>k!=='ground_strike_attempt'):keys;
function render(){const sub=$('#subset').value,native=$('#basis').value==='native';const allScores=sub==='K'?D.kScores:native?D.sensitivityScores:D.scores;const rows=sub==='K'?D.kRows:native?D.sensitivityRows:D.rows;const ss=allScores.filter(s=>(sub==='K'||s.subset===sub)&&s.past_phase===phase&&s.condition==='rich_history_textonly');$('#note').textContent=(sub==='ordinary_registered'?'Ordinary sample: E/F share one bout, G another and H a third. Neighboring cutoffs are correlated. ':sub==='K'?'K4/6/7 are overlapping cutoffs from one selected ground episode; separate from ordinary results. ':'B4/6/7 are overlapping cutoffs before one selected takedown episode; not three independent successes or failures. ')+(native&&sub!=='K'?'Sensitivity view: H4/H12/H16 ground strikes become unknown; H8/G8 stay yes. E16 and all other targets retain frozen subtype references. ':'Frozen independent subtype references. ')+(phase==='all'?'All-phase rows include out-of-domain negatives; use phase-specific rows to judge value.':'');
$('#scores').innerHTML=targets().map(k=>{const s=ss.find(x=>x.target===k);if(!s)return `<tr><td>${names[k]}</td><td colspan="5">No windows in this past phase</td></tr>`;const constant=c=>allScores.find(x=>(sub==='K'||x.subset===sub)&&x.past_phase===phase&&x.condition===c&&x.target===k);return `<tr><td>${names[k]}</td><td class="num"><span class="yes">${s.positives}</span> / <span class="no">${s.negatives}</span> / <span class="unclear">${s.unclear}</span></td><td class="num">${s.true_alerts} / ${s.missed_positives}</td><td class="num">${s.false_alerts} / ${s.negatives}${!s.negatives?' · untested':''}</td><td class="num">${fmt(s.mean_brier)}</td><td class="num">${['always_yes','always_no','uninformative_0.5'].map(c=>fmt(constant(c)?.mean_brier)).join(' / ')}</td></tr>`}).join('');const chosen=$('#target').value;$('#target').innerHTML=targets().map(k=>`<option value="${k}">${names[k]}</option>`).join('');if(targets().includes(chosen))$('#target').value=chosen;renderCases(rows,sub,native);}
function renderCases(rows,sub,native){const k=$('#target').value;const rs=rows.filter(r=>(sub==='K'||r.subset===sub)&&r.condition==='rich_history_textonly'&&r.target===k&&(phase==='all'||r.past_phase===phase));$('#cases').innerHTML=rs.map(r=>{const c=D.cases.find(c=>c.clip===r.clip&&c.cutoff===r.cutoff);const b=c.base,stem=`${c.clip}_${c.cutoff}`,o=native?D.overlays.find(o=>o.clip===c.clip&&o.cutoff===c.cutoff&&o.target===k):null;const ref=o?o.native_reference:c.ref.targets[k];const rationale=c.pred.rationale_by_target[k];const onset=o?.timing_supplement?.onset_intervals?.map(x=>x.map(n=>n.toFixed(3)).join('–')).join(', ')||(ref.onsets_seconds||[]).map(n=>n.toFixed(3)).join(', ');return `<tr><td class="mono">${c.clip} ${c.cutoff}s → ${c.cutoff+4}s</td><td>${esc(c.phase)}</td><td class="num">${Math.round(r.probability*100)}% · ${r.alert?'alert':'no alert'}<div class="bar"><span style="width:${r.probability*100}%"></span></div><details><summary>Why?</summary><p>${esc(rationale)}</p></details></td><td><strong class="${r.truth}">${r.truth.toUpperCase()}</strong>${onset?'<div class="mono">onset '+esc(onset)+'s</div>':''}<details><summary>Visible evidence</summary><pre>${esc(JSON.stringify(ref,null,2))}</pre></details></td><td><a href="${b}evidence/${stem}_00.jpg">Native frames</a><br><a href="${b}evidence/${stem}.sampling.json">Sampling timestamps</a><details><summary>All 13 native pages</summary>${Array.from({length:13},(_,i)=>`<a href="${b}evidence/${stem}_${String(i).padStart(2,'0')}.jpg">Page ${i+1}</a>`).join(' · ')}</details><br><a href="${b}prefixes/${stem}.json">Past input</a> · <a href="${b}predictions/${stem}.json">Forecast</a><br><a href="${b}references/${stem}.json">Frozen reference</a>${o?'<br><a href="native_sensitivity.json">Independent native review</a>':''}</td></tr>`}).join('')||'<tr><td colspan="5">No cases in this phase.</td></tr>';}
document.querySelectorAll('[data-phase]').forEach(b=>b.onclick=()=>{phase=b.dataset.phase;document.querySelectorAll('[data-phase]').forEach(x=>x.classList.toggle('active',x===b));render()});$('#subset').onchange=render;$('#basis').onchange=render;$('#target').onchange=()=>renderCases($('#subset').value==='K'?D.kRows:$('#basis').value==='native'?D.sensitivityRows:D.rows,$('#subset').value,$('#basis').value==='native');render();
</script></html>'''
